"""
Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers.

Args:
    n (int): The number to check.

Returns:
    bool: True if n can be written as the sum of exactly 4 positive even numbers, False otherwise.
"""
# Check if n is even, because the sum of 4 even numbers is always even
if n % 2 != 0:
    return False

# Check all possible combinations of 4 positive even numbers
for a in range(2, n, 2):
    for b in range(a, n, 2):
        for c in range(b, n, 2):
            for d in range(c, n, 2):
                # Check if the sum of the 4 numbers equals n
                if a + b + c + d == n:
                    return True

# If no combination is found, return False
return False
